def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for mode in ("diff", "sum"):
        groups = {}
        valid = True
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = c-r if mode == "diff" else r+c
                    if k in groups and groups[k] != color:
                        valid = False
                    groups[k] = color
        if valid and groups:
            candidates.append((len(groups), mode, groups))
    _, mode, groups = max(candidates, key=lambda x: (x[0], x[1] == "diff"))
    period = next(p for p in range(1, h+w+1)
                  if all(not any((k2-k1) % p == 0 and v1 != v2
                                 for k2, v2 in groups.items())
                         for k1, v1 in groups.items()))
    colors = {k % period: v for k, v in groups.items()}
    # A sparse motif may leave one phase unmarked; continue the observed stripe pattern.
    missing = [i for i in range(period) if i not in colors]
    if len(missing) == 1:
        i = missing[0]
        if period-1 in colors:
            colors[i] = colors[period-1]
        elif (i+1) % period in colors:
            colors[i] = colors[(i+1) % period]
        else:
            colors[i] = colors[max(colors)]
    return [[colors[(c-r if mode == "diff" else r+c) % period]
             for c in range(w)] for r in range(h)]
